update public.dispositivos set texto = $t$para a composição das Câmaras Municipais, será observado o limite máximo de:$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constituição Constitucional nº 58, de 2009"}, {"tipo": "vigencia", "texto": "Produção de efeito"}, {"tipo": "vide", "texto": "Vide ADIN 4307"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 29, IV$i$;
