update public.dispositivos set texto = $t$organização administrativa, judiciária, do Ministério Público e da Defensoria Pública da União e dos Territórios e organização judiciária e do Ministério Público do Distrito Federal;$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 69, de 2012"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 48, IX$i$;
update public.dispositivos set texto = $t$nas operações e prestações que destinem bens e serviços a consumidor final, contribuinte ou não do imposto, localizado em outro Estado, adotar-se-á a alíquota interestadual e caberá ao Estado de localização do destinatário o imposto correspondente à diferença entre a alíquota interna do Estado destinatário e a alíquota interestadual;$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 87, de 2015"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 155, § 2º, VII$i$;
update public.dispositivos set texto = $t$a responsabilidade pelo recolhimento do imposto correspondente à diferença entre a alíquota interna e a interestadual de que trata o inciso VII será atribuída:$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 87, de 2015"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 155, § 2º, VIII$i$;
update public.dispositivos set texto = $t$1% (um por cento) ao Fundo de Participação dos Municípios, que será entregue no primeiro decêndio do mês de setembro de cada ano;$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 112, de 2021"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 159, I, f)$i$;
update public.dispositivos set texto = $t$dispor sobre critérios para a execução equitativa, além de procedimentos que serão adotados quando houver impedimentos legais e técnicos, cumprimento de restos a pagar e limitação das programações de caráter obrigatório, para a realização do disposto nos §§ 11 e 12 do art. 166 .$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 100, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}, {"tipo": "vide", "texto": "Vide ADI 7697"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 9º, III$i$;
update public.dispositivos set texto = $t$A administração tem o dever de executar as programações orçamentárias, adotando os meios e as medidas necessários, com o propósito de garantir a efetiva entrega de bens e serviços à sociedade.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 100, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}, {"tipo": "vide", "texto": "Vide ADI 7697"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 10$i$;
update public.dispositivos set texto = $t$O disposto no § 10 deste artigo, nos termos da lei de diretrizes orçamentárias:$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 102, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 11$i$;
update public.dispositivos set texto = $t$Integrará a lei de diretrizes orçamentárias, para o exercício a que se refere e, pelo menos, para os 2 (dois) exercícios subsequentes, anexo com previsão de agregados fiscais e a proporção dos recursos para investimentos que serão alocados na lei orçamentária anual para a continuidade daqueles em andamento.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 102, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 12$i$;
update public.dispositivos set texto = $t$O disposto no inciso III do § 9º e nos §§ 10, 11 e 12 deste artigo aplica-se exclusivamente aos orçamentos fiscal e da seguridade social da União.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 102, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 13$i$;
update public.dispositivos set texto = $t$A lei orçamentária anual poderá conter previsões de despesas para exercícios seguintes, com a especificação dos investimentos plurianuais e daqueles em andamento.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 102, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 14$i$;
update public.dispositivos set texto = $t$A União organizará e manterá registro centralizado de projetos de investimento contendo, por Estado ou Distrito Federal, pelo menos, análises de viabilidade, estimativas de custos e informações sobre a execução física e financeira.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Emenda Constitucional nº 102, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 165, § 15$i$;
update public.dispositivos set texto = $t$A garantia de execução de que trata o § 11 deste artigo aplica-se também às programações incluídas por todas as emendas de iniciativa de bancada de parlamentares de Estado ou do Distrito Federal, no montante de até 1% (um por cento) da receita corrente líquida realizada no exercício anterior.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 100, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}, {"tipo": "vide", "texto": "Vide"}, {"tipo": "vide", "texto": "Vide"}, {"tipo": "vide", "texto": "Vide ADI 7697"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 166, § 12$i$;
update public.dispositivos set texto = $t$As programações orçamentárias previstas nos §§ 11 e 12 deste artigo não serão de execução obrigatória nos casos dos impedimentos de ordem técnica.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 100, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}, {"tipo": "vide", "texto": "Vide ADI 7697"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 166, § 13$i$;
update public.dispositivos set texto = $t$Para fins de cumprimento do disposto nos §§ 11 e 12 deste artigo, os órgãos de execução deverão observar, nos termos da lei de diretrizes orçamentárias, cronograma para análise e verificação de eventuais impedimentos das programações e demais procedimentos necessários à viabilização da execução dos respectivos montantes.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Emenda Constitucional nº 100, de 2019"}, {"tipo": "vigencia", "texto": "Produção de efeito"}, {"tipo": "vide", "texto": "Vide ADI 7697"}]$j$::jsonb where id = $i$CF-1988|corpo|art. 166, § 14$i$;
