update public.dispositivos set texto = $t$O empregador que infringir o disposto no caput e no § 1º do art. 29 desta Consolidação ficará sujeito a multa no valor de R$ 3.000,00 (três mil reais) por empregado prejudicado, acrescido de igual valor em cada reincidência.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.438, de 2022"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$DL-5452-1943|corpo|art. 29-A$i$;
update public.dispositivos set texto = $t$No caso de microempresa ou de empresa de pequeno porte, o valor final da multa aplicada será de R$ 800,00 (oitocentos reais) por empregado prejudicado.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.438, de 2022"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$DL-5452-1943|corpo|art. 29-A, § 1º$i$;
update public.dispositivos set texto = $t$A infração de que trata o caput deste artigo constitui exceção ao critério da dupla visita.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.438, de 2022"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$DL-5452-1943|corpo|art. 29-A, § 2º$i$;
update public.dispositivos set texto = $t$Na hipótese de não serem realizadas as anotações a que se refere o § 2º do art. 29 desta Consolidação, o empregador ficará sujeito a multa no valor de R$ 600,00 (seiscentos reais) por empregado prejudicado.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.438, de 2022"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$DL-5452-1943|corpo|art. 29-B$i$;
update public.dispositivos set texto = $t$Não cumprida a obrigação, responde o devedor por perdas e danos, mais juros, atualização monetária e honorários de advogado.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 389$i$;
update public.dispositivos set texto = $t$Na hipótese de o índice de atualização monetária não ter sido convencionado ou não estar previsto em lei específica, será aplicada a variação do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado e divulgado pela Fundação Instituto Brasileiro de Geografia e Estatística (IBGE), ou do índice que vier a substituí-lo.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 389, parágrafo único$i$;
update public.dispositivos set texto = $t$Responde o devedor pelos prejuízos a que sua mora der causa, mais juros, atualização dos valores monetários e honorários de advogado.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 395$i$;
update public.dispositivos set texto = $t$As perdas e danos, nas obrigações de pagamento em dinheiro, serão pagas com atualização monetária, juros, custas e honorários de advogado, sem prejuízo da pena convencional.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 404$i$;
update public.dispositivos set texto = $t$Quando não forem convencionados, ou quando o forem sem taxa estipulada, ou quando provierem de determinação da lei, os juros serão fixados de acordo com a taxa legal.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 406$i$;
update public.dispositivos set texto = $t$A taxa legal corresponderá à taxa referencial do Sistema Especial de Liquidação e de Custódia (Selic), deduzido o índice de atualização monetária de que trata o parágrafo único do art. 389 deste Código.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 406, § 1º$i$;
update public.dispositivos set texto = $t$Caso a taxa legal apresente resultado negativo, este será considerado igual a 0 (zero) para efeito de cálculo dos juros no período de referência.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 406, § 3º$i$;
update public.dispositivos set texto = $t$Na hipótese de inexecução do contrato, se esta se der:$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 418$i$;
update public.dispositivos set texto = $t$por parte de quem deu as arras, poderá a outra parte ter o contrato por desfeito, retendo-as;$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 418, I$i$;
update public.dispositivos set texto = $t$por parte de quem recebeu as arras, poderá quem as deu haver o contrato por desfeito e exigir a sua devolução mais o equivalente, com atualização monetária, juros e honorários de advogado.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 418, II$i$;
update public.dispositivos set texto = $t$Destinando-se o mútuo a fins econômicos, presumem-se devidos juros.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 591$i$;
update public.dispositivos set texto = $t$Se a taxa de juros não for pactuada, aplica-se a taxa legal prevista no art. 406 deste Código.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 591, parágrafo único$i$;
update public.dispositivos set texto = $t$O condômino que não pagar a sua contribuição ficará sujeito à correção monetária e aos juros moratórios convencionados ou, não sendo previstos, aos juros estabelecidos no art. 406 deste Código, bem como à multa de até 2% (dois por cento) sobre o débito.$t$, revogado = false, anotacoes = $j$[{"tipo": "redacao_dada", "texto": "Redação dada pela Lei nº 14.905, de 2024"}, {"tipo": "vigencia", "texto": "Produção de efeitos"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 1.336, § 1º$i$;
update public.dispositivos set texto = $t$Caso o regulamento do fundo estabeleça classes de cotas com direitos e obrigações distintos, nos termos do inciso III do caput do art. 1.368-D deste Código, aplica-se o disposto neste artigo a cada classe de cotas, individualmente considerada.$t$, revogado = false, anotacoes = $j$[{"tipo": "incluido", "texto": "Incluído pela Lei nº 14.754, de 2023"}, {"tipo": "vigencia", "texto": "Produção de efeito"}]$j$::jsonb where id = $i$LEI-10406-2002|corpo|art. 1.368-E, § 3º$i$;
