update public.versoes_dispositivo set texto = $t$É assegurada, nos termos da lei, à União, aos Estados, ao Distrito Federal e aos Municípios a participação no resultado da exploração de petróleo ou gás natural, de recursos hídricos para fins de geração de energia elétrica e de outros recursos minerais no respectivo território, plataforma continental, mar territorial ou zona econômica exclusiva, ou compensação financeira por essa exploração.$t$, hash = 'ed66eac4a54ed5cbbc3d2bf0e3b2ba7f0724807a08dcd2ba3b9a0debe8a5cc2d' where dispositivo_id = $i$CF-1988|corpo|art. 20, § 1º$i$;
