update public.versoes_dispositivo set texto = $t$nas operações e prestações que destinem bens e serviços a consumidor final, contribuinte ou não do imposto, localizado em outro Estado, adotar-se-á a alíquota interestadual e caberá ao Estado de localização do destinatário o imposto correspondente à diferença entre a alíquota interna do Estado destinatário e a alíquota interestadual;$t$, hash = '3ccc82e955e65b332f22393b1977c699049db5e87553a221e3c923740bcad053' where dispositivo_id = $i$CF-1988|corpo|art. 155, § 2º, VII$i$;
