update public.versoes_dispositivo set texto = $t$dispor sobre critérios para a execução equitativa, além de procedimentos que serão adotados quando houver impedimentos legais e técnicos, cumprimento de restos a pagar e limitação das programações de caráter obrigatório, para a realização do disposto nos §§ 11 e 12 do art. 166 .$t$, hash = '3f1496d3dd6f8ec1e78ff2a5b5d7ded02e41c56456e1923912184d36d0911b7e' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 9º, III$i$;
update public.versoes_dispositivo set texto = $t$A administração tem o dever de executar as programações orçamentárias, adotando os meios e as medidas necessários, com o propósito de garantir a efetiva entrega de bens e serviços à sociedade.$t$, hash = '5a9031c410f43c873ba8db5b4b6629881ec194bc0087bc7a7f3dbec242191991' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 10$i$;
update public.versoes_dispositivo set texto = $t$O disposto no § 10 deste artigo, nos termos da lei de diretrizes orçamentárias:$t$, hash = '022cca09c917e2a755ee3f38472b85a39b1ff12870b6d660df02c8b43ddb73cc' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 11$i$;
update public.versoes_dispositivo set texto = $t$Integrará a lei de diretrizes orçamentárias, para o exercício a que se refere e, pelo menos, para os 2 (dois) exercícios subsequentes, anexo com previsão de agregados fiscais e a proporção dos recursos para investimentos que serão alocados na lei orçamentária anual para a continuidade daqueles em andamento.$t$, hash = '3e6d9e6edc4e8776b065b352c3a4a801810136b394cf92533f10e0e5e799d1e8' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 12$i$;
update public.versoes_dispositivo set texto = $t$O disposto no inciso III do § 9º e nos §§ 10, 11 e 12 deste artigo aplica-se exclusivamente aos orçamentos fiscal e da seguridade social da União.$t$, hash = '216f3cd66a381e7a95e24a8eaf1c93f5189aed2cc0b1b279ea119e9455b49ce2' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 13$i$;
update public.versoes_dispositivo set texto = $t$A lei orçamentária anual poderá conter previsões de despesas para exercícios seguintes, com a especificação dos investimentos plurianuais e daqueles em andamento.$t$, hash = '980aebedf90495771f120a761273fec9d4ced267baa02f1cd7290bccdc09137b' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 14$i$;
update public.versoes_dispositivo set texto = $t$A União organizará e manterá registro centralizado de projetos de investimento contendo, por Estado ou Distrito Federal, pelo menos, análises de viabilidade, estimativas de custos e informações sobre a execução física e financeira.$t$, hash = 'a9d931a99a3ecfe708755fc485a1e34947ce76b4b13e55890a7b5dea2ff199fc' where dispositivo_id = $i$CF-1988|corpo|art. 165, § 15$i$;
update public.versoes_dispositivo set texto = $t$A garantia de execução de que trata o § 11 deste artigo aplica-se também às programações incluídas por todas as emendas de iniciativa de bancada de parlamentares de Estado ou do Distrito Federal, no montante de até 1% (um por cento) da receita corrente líquida realizada no exercício anterior.$t$, hash = 'b2191e376d3722f8de26374cc3e783698e75a008ff3f8d67c694a6ba253f5306' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 12$i$;
update public.versoes_dispositivo set texto = $t$As programações orçamentárias previstas nos §§ 11 e 12 deste artigo não serão de execução obrigatória nos casos dos impedimentos de ordem técnica.$t$, hash = 'b4a0bf7ad1d790d637985ac0f2e29645e88ab7652479abd835715593c498881b' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 13$i$;
update public.versoes_dispositivo set texto = $t$Para fins de cumprimento do disposto nos §§ 11 e 12 deste artigo, os órgãos de execução deverão observar, nos termos da lei de diretrizes orçamentárias, cronograma para análise e verificação de eventuais impedimentos das programações e demais procedimentos necessários à viabilização da execução dos respectivos montantes.$t$, hash = '49de995ccb0238051ce0476759b166ff3d5728bd1cf2708ded228f1338149524' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 14$i$;
update public.versoes_dispositivo set texto = $t$;$t$, hash = '41b805ea7ac014e23556e98bb374702a08344268f92489a02f0880849394a1e4' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 14, I$i$;
update public.versoes_dispositivo set texto = $t$;$t$, hash = '41b805ea7ac014e23556e98bb374702a08344268f92489a02f0880849394a1e4' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 14, II$i$;
update public.versoes_dispositivo set texto = $t$;$t$, hash = '41b805ea7ac014e23556e98bb374702a08344268f92489a02f0880849394a1e4' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 14, III$i$;
update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 14, IV$i$;
update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 15$i$;
update public.versoes_dispositivo set texto = $t$Quando a transferência obrigatória da União para a execução da programação prevista nos §§ 11 e 12 deste artigo for destinada a Estados, ao Distrito Federal e a Municípios, independerá da adimplência do ente federativo destinatário e não integrará a base de cálculo da receita corrente líquida para fins de aplicação dos limites de despesa de pessoal de que trata o caput do art. 169.$t$, hash = '1630ee6394534511ee48582cf4524556c969c24f5dd3dfe3d5aa7c38ddbbe3f2' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 16$i$;
update public.versoes_dispositivo set texto = $t$Se for verificado que a reestimativa da receita e da despesa poderá resultar no não cumprimento da meta de resultado fiscal estabelecida na lei de diretrizes orçamentárias, os montantes previstos nos §§ 11 e 12 deste artigo poderão ser reduzidos em até a mesma proporção da limitação incidente sobre o conjunto das demais despesas discricionárias.$t$, hash = '2c3dc7860ba9351f37b4180b5a35af89da0c294b00e84a8aceee10a622305f95' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 18$i$;
update public.versoes_dispositivo set texto = $t$As programações de que trata o § 12 deste artigo, quando versarem sobre o início de investimentos com duração de mais de 1 (um) exercício financeiro ou cuja execução já tenha sido iniciada, deverão ser objeto de emenda pela mesma bancada estadual, a cada exercício, até a conclusão da obra ou do empreendimento.$t$, hash = 'f8986430b589541f4a6b69bd7f6fb0c9066a521c874eeb218dfda2cc6a033a1c' where dispositivo_id = $i$CF-1988|corpo|art. 166, § 20$i$;
update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$CF-1988|ADCT|art. 76, § 1º$i$;
update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$CF-1988|ADCT|art. 76, § 3º$i$;
update public.versoes_dispositivo set texto = $t$Excetuam-se da desvinculação de que trata o caput:$t$, hash = '556eabbcad8550dbeb5d06527eefc334aa7bdabaed8b22616c6aff8378f07255' where dispositivo_id = $i$CF-1988|ADCT|art. 76-A, parágrafo único$i$;
update public.versoes_dispositivo set texto = $t$recursos destinados ao financiamento das ações e serviços públicos de saúde e à manutenção e desenvolvimento do ensino de que tratam, respectivamente, os incisos II e III do § 2º do art. 198 e o art. 212 da Constituição Federal;$t$, hash = '62065e73d535db98ca13258df17716ca6259ded72a935d8384a8db617f0d329b' where dispositivo_id = $i$CF-1988|ADCT|art. 76-A, parágrafo único, I$i$;
update public.versoes_dispositivo set texto = $t$receitas que pertencem aos Municípios decorrentes de transferências previstas na Constituição Federal;$t$, hash = '377273e6931689335a791b3421c258c7ffac11ca5c3791097ee1cecd1144e997' where dispositivo_id = $i$CF-1988|ADCT|art. 76-A, parágrafo único, II$i$;
update public.versoes_dispositivo set texto = $t$receitas de contribuições previdenciárias e de assistência à saúde dos servidores;$t$, hash = 'b4de345ed5c6d2235503fcfdfefe8691d7209e04a3ca002078b144f3308b6eb2' where dispositivo_id = $i$CF-1988|ADCT|art. 76-A, parágrafo único, III$i$;
update public.versoes_dispositivo set texto = $t$demais transferências obrigatórias e voluntárias entre entes da Federação com destinação especificada em lei;$t$, hash = 'e70f40c84b1416265989b250b81993df784cf54ac1ca976c204975014d44aebd' where dispositivo_id = $i$CF-1988|ADCT|art. 76-A, parágrafo único, IV$i$;
update public.versoes_dispositivo set texto = $t$fundos instituídos pelo Poder Judiciário, pelos Tribunais de Contas, pelo Ministério Público, pelas Defensorias Públicas e pelas Procuradorias-Gerais dos Estados e do Distrito Federal.$t$, hash = '2de876f79825506cd61b0f457c6116349600dbe77946a11140d27c310c341813' where dispositivo_id = $i$CF-1988|ADCT|art. 76-A, parágrafo único, V$i$;
update public.versoes_dispositivo set texto = $t$receitas de contribuições previdenciárias e de assistência à saúde dos servidores;$t$, hash = 'b4de345ed5c6d2235503fcfdfefe8691d7209e04a3ca002078b144f3308b6eb2' where dispositivo_id = $i$CF-1988|ADCT|art. 76-B, § 1º, II$i$;
update public.versoes_dispositivo set texto = $t$transferências obrigatórias e voluntárias entre entes da Federação com destinação especificada em lei;$t$, hash = '2b5eab658271e771aaa5dd2594023090b46e4ae7c9443b96989b142151cb640e' where dispositivo_id = $i$CF-1988|ADCT|art. 76-B, § 1º, III$i$;
update public.versoes_dispositivo set texto = $t$fundos instituídos pelo Tribunal de Contas do Município.$t$, hash = '1e0bb26a0a64dde065ad0fe776a7c542585b7e635f970a6611aa721a8635a486' where dispositivo_id = $i$CF-1988|ADCT|art. 76-B, § 1º, IV$i$;
update public.versoes_dispositivo set texto = $t$O empregador que infringir o disposto no caput e no § 1º do art. 29 desta Consolidação ficará sujeito a multa no valor de R$ 3.000,00 (três mil reais) por empregado prejudicado, acrescido de igual valor em cada reincidência.$t$, hash = '0e7bb41593d9067545d25500a5d2a76b61a86056e9afdf1c10aab5214c53ebc5' where dispositivo_id = $i$DL-5452-1943|corpo|art. 29-A$i$;
update public.versoes_dispositivo set texto = $t$No caso de microempresa ou de empresa de pequeno porte, o valor final da multa aplicada será de R$ 800,00 (oitocentos reais) por empregado prejudicado.$t$, hash = '9816506432a91965f2779a6e608276d68e18fa9b7cbebc08f6fdec7cae1474be' where dispositivo_id = $i$DL-5452-1943|corpo|art. 29-A, § 1º$i$;
update public.versoes_dispositivo set texto = $t$A infração de que trata o caput deste artigo constitui exceção ao critério da dupla visita.$t$, hash = 'b4c5eb3b4d6359f37018f3e56d54d025ca4c8c4821ca81232a276555692f9678' where dispositivo_id = $i$DL-5452-1943|corpo|art. 29-A, § 2º$i$;
update public.versoes_dispositivo set texto = $t$Na hipótese de não serem realizadas as anotações a que se refere o § 2º do art. 29 desta Consolidação, o empregador ficará sujeito a multa no valor de R$ 600,00 (seiscentos reais) por empregado prejudicado.$t$, hash = '85ca59f61a72bfddf75ee0846377068536316585a4bd9203cacd62cc92127bf3' where dispositivo_id = $i$DL-5452-1943|corpo|art. 29-B$i$;
update public.versoes_dispositivo set texto = $t$Não cumprida a obrigação, responde o devedor por perdas e danos, mais juros, atualização monetária e honorários de advogado.$t$, hash = 'e3a4b7d2f9e1ffc5cfcc93662c0a64036d9d2216e66931d172c44fd04b37c4ba' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 389$i$;
update public.versoes_dispositivo set texto = $t$Na hipótese de o índice de atualização monetária não ter sido convencionado ou não estar previsto em lei específica, será aplicada a variação do Índice Nacional de Preços ao Consumidor Amplo (IPCA), apurado e divulgado pela Fundação Instituto Brasileiro de Geografia e Estatística (IBGE), ou do índice que vier a substituí-lo.$t$, hash = 'f6001638e2a78b1c692189d7c396b2101fb10448dfaf5aee92ad1044fac1f36e' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 389, parágrafo único$i$;
update public.versoes_dispositivo set texto = $t$Responde o devedor pelos prejuízos a que sua mora der causa, mais juros, atualização dos valores monetários e honorários de advogado.$t$, hash = 'e1f68f1d55409884ff223949e047cbaca43eacb865a5464a5eb0eed0592a6a91' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 395$i$;
update public.versoes_dispositivo set texto = $t$As perdas e danos, nas obrigações de pagamento em dinheiro, serão pagas com atualização monetária, juros, custas e honorários de advogado, sem prejuízo da pena convencional.$t$, hash = '390e6ba5408bed722888a89b705516c7e79b4eaf6890e462bae1c2c66ad4f342' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 404$i$;
update public.versoes_dispositivo set texto = $t$Quando não forem convencionados, ou quando o forem sem taxa estipulada, ou quando provierem de determinação da lei, os juros serão fixados de acordo com a taxa legal.$t$, hash = '45725c5630f739eb5db4cfe3aadf2037027c52348c23d25c2715cdeee6616079' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 406$i$;
update public.versoes_dispositivo set texto = $t$A taxa legal corresponderá à taxa referencial do Sistema Especial de Liquidação e de Custódia (Selic), deduzido o índice de atualização monetária de que trata o parágrafo único do art. 389 deste Código.$t$, hash = 'c1895ce4f880d112e5becbd385c09c9a13bf45af4d2422792c2248f0bce14353' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 406, § 1º$i$;
update public.versoes_dispositivo set texto = $t$Caso a taxa legal apresente resultado negativo, este será considerado igual a 0 (zero) para efeito de cálculo dos juros no período de referência.$t$, hash = '50514ea2094cb64d6cadaa717488f44e4547932662c514b538d552553fe3e6c7' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 406, § 3º$i$;
update public.versoes_dispositivo set texto = $t$Na hipótese de inexecução do contrato, se esta se der:$t$, hash = 'ff31d8adca108d685a4c147ee38f4eae8d9e3ca3e33b893829f1aee185bb9b52' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 418$i$;
update public.versoes_dispositivo set texto = $t$por parte de quem deu as arras, poderá a outra parte ter o contrato por desfeito, retendo-as;$t$, hash = 'd09a8298f4d16230cf3dce88356857b52ceb1a826126ebfe59a459824a2407f9' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 418, I$i$;
update public.versoes_dispositivo set texto = $t$por parte de quem recebeu as arras, poderá quem as deu haver o contrato por desfeito e exigir a sua devolução mais o equivalente, com atualização monetária, juros e honorários de advogado.$t$, hash = '6b17ef0784c886cfa6fec3472ec3e301cd0fbfbb0edc32955ec43724c7d2b2e0' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 418, II$i$;
update public.versoes_dispositivo set texto = $t$Destinando-se o mútuo a fins econômicos, presumem-se devidos juros.$t$, hash = '8218881bab315824338a245c23ce235d30cb1fdf1d4e11ed57f2ac585c1e1b5a' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 591$i$;
update public.versoes_dispositivo set texto = $t$Se a taxa de juros não for pactuada, aplica-se a taxa legal prevista no art. 406 deste Código.$t$, hash = 'bf7aa65e1f9ae1065f7f41875bb7a8b442d825b06a6d92e8ed2552e54b259979' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 591, parágrafo único$i$;
update public.versoes_dispositivo set texto = $t$O condômino que não pagar a sua contribuição ficará sujeito à correção monetária e aos juros moratórios convencionados ou, não sendo previstos, aos juros estabelecidos no art. 406 deste Código, bem como à multa de até 2% (dois por cento) sobre o débito.$t$, hash = '189fb29d2d482b99a9b15dd8c8b97d259747c383c5c7c93c818397c9ca006879' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 1.336, § 1º$i$;
update public.versoes_dispositivo set texto = $t$Caso o regulamento do fundo estabeleça classes de cotas com direitos e obrigações distintos, nos termos do inciso III do caput do art. 1.368-D deste Código, aplica-se o disposto neste artigo a cada classe de cotas, individualmente considerada.$t$, hash = 'd641f465975dec03e3862f77cf0af22017e2fa38a54f19fe2a4f323ee3790aa2' where dispositivo_id = $i$LEI-10406-2002|corpo|art. 1.368-E, § 3º$i$;
update public.versoes_dispositivo set texto = $t$a receita obtida pelo devedor não será computada na apuração da base de cálculo da Contribuição para o Programa de Integração Social (PIS) e para o Programa de Formação do Patrimônio do Servidor Público (Pasep) e da Contribuição para o Financiamento da Seguridade Social (Cofins);$t$, hash = '602452f19f543fcfe2b425b0404c82bc0828113a086c50a11111ce4c887ea54a' where dispositivo_id = $i$LEI-11101-2005|corpo|art. 50-A, I$i$;
update public.versoes_dispositivo set texto = $t$cobrar impostos e a contribuição de que trata o inciso V do art. 195 da Constituição Federal sobre:$t$, hash = '944091563b07e0f563226b933fd03d982ed0935987b3956d28b1fc9db2ad4fc0' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 9º, IV$i$;
update public.versoes_dispositivo set texto = $t$entidades religiosas e templos de qualquer culto, inclusive suas organizações assistenciais e beneficentes;$t$, hash = '56513d5e81b3431230b74d0d24433fa56f06d27c4b8c57d9c2e10479b704fab5' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 9º, IV, b)$i$;
