update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 87$i$;
update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 88$i$;
update public.versoes_dispositivo set texto = $t$$t$, hash = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 89$i$;
update public.versoes_dispositivo set texto = $t$O Tribunal de Contas da União comunicará ao Banco do Brasil S.A., conforme os prazos a seguir especificados, os coeficientes individuais de participação nos fundos previstos no art. 159, inciso I, alíneas “a”, “b” e “d”, da Constituição Federal que prevalecerão no exercício subsequente:$t$, hash = 'c0496772e655c1645ea78862b2edbdf3d8b345685754513e74b837f68cd96b22' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 92$i$;
update public.versoes_dispositivo set texto = $t$até o último dia útil do mês de março de cada exercício financeiro, para cada Estado e para o Distrito Federal;$t$, hash = '60742cb3b054e4f229fbac9e6b124b379ebe2f053e1c4a0d5a2b86043648b972' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 92, I$i$;
update public.versoes_dispositivo set texto = $t$até o último dia útil de cada exercício financeiro, para cada Município.$t$, hash = '49c211cf05f477006e226018a666a9c991d364d84268f0686afb6f153bed8a49' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 92, II$i$;
update public.versoes_dispositivo set texto = $t$Far-se-á nova comunicação sempre que houver, transcorrido o prazo fixado no inciso I do caput, a criação de novo Estado a ser implantado no exercício subsequente.$t$, hash = '9f22b573b2bc05672ef13d796d7a8b9449f87c42eae45cbca662b6785bfa8fed' where dispositivo_id = $i$LEI-5172-1966|corpo|art. 92, parágrafo único$i$;
