update public.versoes_dispositivo set texto = $t$A participação do segurado especial em sociedade empresária, em sociedade simples, como empresário individual ou como titular de empresa individual de responsabilidade limitada de objeto ou âmbito agrícola, agroindustrial ou agroturístico, considerada microempresa nos termos da Lei Complementar no 123, de 14 de dezembro de 2006, não o exclui de tal categoria previdenciária, desde que, mantido o exercício da sua atividade rural na forma do inciso VII do caput e do § 1o, a pessoa jurídica componha-se apenas de segurados de igual natureza e sedie-se no mesmo Município ou em Município limítrofe àquele em que eles desenvolvam suas atividades.$t$, hash = 'eb1f94dd29f7d0ffad508b3c323ddca547a134c8f746903290348a50e33dba1c' where dispositivo_id = $i$LEI-8213-1991|corpo|art. 11, § 12$i$;
